import { replayArguments } from "./args.js";
import { HELP, REPLAY_ARGUMENTS_FLAG } from "./constants.js";
import { printOutcome } from "./local.js";
import { UsageExit } from "./options.js";
import { annotate, execute, runnerExitCode } from "./runner.js";
import { deps, Interrupt, print, printError, progress } from "./runtime.js";
import { configureSecrets } from "./secrets.js";
import { initialize } from "./workflow.js";
function printJson(value) {
    print(JSON.stringify(value, null, 2));
}
async function dispatchCommand(argv) {
    if (argv[0] === "--cloud-init" || argv[0] === "--cloud-update") {
        printJson(await initialize(argv.slice(1), argv[0]));
        return 0;
    }
    if (argv[0] === "--cloud-secrets") {
        printJson(await configureSecrets(argv.slice(1)));
        return 0;
    }
    if (argv[0] === REPLAY_ARGUMENTS_FLAG) {
        printJson(replayArguments(argv.slice(1)));
        return 0;
    }
    if (argv.length === 1 && argv[0] === "--cloud-execute") {
        const result = await execute();
        annotate(result);
        return runnerExitCode(result);
    }
    if (argv.includes("-h") || argv.includes("--help")) {
        deps.stdout(HELP);
        return 0;
    }
    const [record, found] = await deps.runCli(argv);
    if (found !== null) {
        return printOutcome(found);
    }
    printJson(record);
    return record.state === "completed" ? (record.exitCode ?? 0) : 0;
}
export async function main(argv) {
    try {
        return await dispatchCommand(argv);
    }
    catch (error) {
        if (error instanceof UsageExit) {
            return error.code;
        }
        if (error instanceof Interrupt) {
            progress("Detached. A GitHub run that already started continues; follow it with --cloud-watch and the printed execution UUID, or stop it with --cloud-cancel and remove its snapshot branch with --cloud-cleanup once it completes");
            return 130;
        }
        printError(`Cloud replay: ${error instanceof Error ? error.message : String(error)}`);
        return 1;
    }
}
